CREATE TABLE IF NOT EXISTS marketplace_publishers(id INTEGER PRIMARY KEY AUTOINCREMENT,publisher_key TEXT NOT NULL UNIQUE,name TEXT NOT NULL,public_key TEXT NOT NULL,trust_status TEXT NOT NULL DEFAULT 'untrusted' CHECK(trust_status IN('trusted','untrusted','revoked')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS marketplace_packages(id INTEGER PRIMARY KEY AUTOINCREMENT,extension_key TEXT NOT NULL,version TEXT NOT NULL,publisher_id INTEGER REFERENCES marketplace_publishers(id) ON DELETE SET NULL,package_type TEXT NOT NULL,catalog_meta_json TEXT NOT NULL DEFAULT '{}',checksum TEXT NOT NULL,signature TEXT NOT NULL DEFAULT '',license_product_key TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','revoked','hidden')),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(extension_key,version));
CREATE TABLE IF NOT EXISTS marketplace_entitlements(id INTEGER PRIMARY KEY AUTOINCREMENT,extension_key TEXT NOT NULL,subject_type TEXT NOT NULL,subject_value TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'active' CHECK(status IN('active','expired','revoked')),expires_at TEXT,source TEXT NOT NULL DEFAULT 'local',metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(extension_key,subject_type,subject_value));
CREATE TABLE IF NOT EXISTS marketplace_provenance(id INTEGER PRIMARY KEY AUTOINCREMENT,extension_key TEXT NOT NULL,version TEXT NOT NULL,publisher_key TEXT,checksum TEXT NOT NULL,signature_status TEXT NOT NULL,license_status TEXT NOT NULL,action TEXT NOT NULL,actor_id INTEGER REFERENCES users(id) ON DELETE SET NULL,metadata_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS marketplace_revocations(id INTEGER PRIMARY KEY AUTOINCREMENT,extension_key TEXT NOT NULL,version TEXT,publisher_key TEXT,reason TEXT NOT NULL,revoked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(extension_key,version,publisher_key));
INSERT OR IGNORE INTO schema_migrations(version) VALUES('10.20.0');